/* Decodes the golden datagrams generated by the Rust encoder.
 * cc -std=c99 -Wall -Wextra -Werror -pedantic -I.. test_virtual_sync.c && ./a.out */
#define VIRTUAL_SYNC_IMPLEMENTATION
#include "../virtual_sync.h"
#include "vectors.h"

#include <math.h>
#include <stdio.h>
#include <string.h>

static int failures = 0;
#define CHECK(condition)                                                        \
    do {                                                                        \
        if (!(condition)) {                                                     \
            printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #condition);         \
            failures++;                                                         \
        }                                                                       \
    } while (0)

static int parse(const uint8_t *data, size_t len, const vs_key *key, vs_packet *packet, int kind) {
    int result = vs_parse(data, len, key, packet);
    return result == VS_OK && packet->kind == kind;
}

int main(void) {
    vs_key key, wrong;
    vs_packet p;
    CHECK(vs_derive_key(VS_TEST_PASSPHRASE, &key));
    CHECK(!vs_derive_key("   ", &wrong));
    CHECK(vs_derive_key("other", &wrong));
    {
        /* SipHash reference vector: key 00..0f, message 00..0e. */
        vs_key ref = {0x0706050403020100ULL, 0x0f0e0d0c0b0a0908ULL};
        uint8_t msg[15];
        int i;
        for (i = 0; i < 15; i++) msg[i] = (uint8_t)i;
        CHECK(vs_siphash24(ref, msg, 15) == 0xa129ca6149be45e5ULL);
    }
    {
        vs_announce a;
        CHECK(parse(VS_VECTOR_ANNOUNCE, sizeof VS_VECTOR_ANNOUNCE, &key, &p, VS_ANNOUNCE));
        CHECK(vs_read_announce(&p, &a) == VS_OK);
        CHECK(strcmp(a.name, "Main room") == 0 && a.streams == 15 && a.zones == 4 && a.port == 50000);
        CHECK(p.session == 0x12345678 && p.sequence == 100);
    }
    {
        vs_clock c;
        CHECK(parse(VS_VECTOR_CLOCK, sizeof VS_VECTOR_CLOCK, &key, &p, VS_CLOCK));
        CHECK(vs_read_clock(&p, &c) == VS_OK);
        CHECK(c.leader_us == 5000000 && c.beat == 33.5 && c.bpm == 128.0f);
        CHECK(c.beats_per_bar == 4 && c.playing == 1);
        /* Half a second later at 128 BPM is 1.0667 beats on. */
        CHECK(fabs(vs_beat_at(&c, 5500000) - (33.5 + 128.0 / 120.0)) < 1e-9);
    }
    {
        uint32_t id;
        float value;
        uint8_t snapshot = 9;
        CHECK(parse(VS_VECTOR_CONTROLS, sizeof VS_VECTOR_CONTROLS, &key, &p, VS_CONTROLS));
        CHECK(vs_controls_count(&p, &snapshot) == 2 && snapshot == 0);
        CHECK(vs_control_at(&p, 0, &id, &value) == VS_OK);
        CHECK(id == vs_control_id("deck.0.level") && value == 0.75f);
        CHECK(vs_control_at(&p, 1, &id, &value) == VS_OK);
        CHECK(id == vs_control_id("master.blackout") && value == 1.0f);
        CHECK(vs_control_at(&p, 2, &id, &value) != VS_OK);
    }
    {
        vs_audio a;
        CHECK(parse(VS_VECTOR_AUDIO, sizeof VS_VECTOR_AUDIO, &key, &p, VS_AUDIO));
        CHECK(vs_read_audio(&p, &a) == VS_OK);
        CHECK(a.level == 0.5f && a.bass == 0.875f && a.hit == 1.0f && a.bands[7] == 0.875f);
    }
    {
        const uint8_t *rgb;
        CHECK(parse(VS_VECTOR_ZONES, sizeof VS_VECTOR_ZONES, &key, &p, VS_ZONES));
        CHECK(vs_zones_count(&p) == 4);
        rgb = vs_zone_rgb(&p, 3);
        CHECK(rgb && rgb[0] == 10 && rgb[1] == 20 && rgb[2] == 30);
        CHECK(vs_zone_rgb(&p, 4) == NULL);
    }
    {
        uint8_t hello[64];
        size_t n = vs_build_hello(hello, sizeof hello, "Strip", VS_NODE_LIGHT,
                                  VS_STREAM_CLOCK | VS_STREAM_ZONES, 0x12345678, 101, &key);
        CHECK(n == sizeof VS_VECTOR_HELLO && memcmp(hello, VS_VECTOR_HELLO, n) == 0);
        CHECK(vs_build_hello(hello, 10, "Strip", VS_NODE_LIGHT, 0, 0, 0, &key) == 0);
    }
    /* Security: wrong key, missing key, tampering, and unsigned shows. */
    CHECK(vs_parse(VS_VECTOR_CLOCK, sizeof VS_VECTOR_CLOCK, &wrong, &p) == VS_ERR_SIGNATURE);
    CHECK(vs_parse(VS_VECTOR_CLOCK, sizeof VS_VECTOR_CLOCK, NULL, &p) == VS_ERR_SIGNATURE);
    {
        uint8_t copy[sizeof VS_VECTOR_CLOCK];
        memcpy(copy, VS_VECTOR_CLOCK, sizeof copy);
        copy[25] ^= 1;
        CHECK(vs_parse(copy, sizeof copy, &key, &p) == VS_ERR_SIGNATURE);
    }
    CHECK(parse(VS_VECTOR_CLOCK_UNSIGNED, sizeof VS_VECTOR_CLOCK_UNSIGNED, NULL, &p, VS_CLOCK));
    CHECK(vs_parse(VS_VECTOR_CLOCK_UNSIGNED, sizeof VS_VECTOR_CLOCK_UNSIGNED, &key, &p) == VS_ERR_SIGNATURE);
    {
        vs_window w;
        memset(&w, 0, sizeof w);
        CHECK(vs_window_accept(&w, 7, 10) && !vs_window_accept(&w, 7, 10));
        CHECK(vs_window_accept(&w, 7, 12) && vs_window_accept(&w, 7, 11) && !vs_window_accept(&w, 7, 11));
        CHECK(vs_window_accept(&w, 8, 1));
    }
    if (failures == 0) printf("virtual_sync.h: all checks passed\n");
    return failures != 0;
}
